    @Test
    @DisplayName("Test /openapi/v1/order/test - Test new order (LIMIT)")
    public void testNewOrderLimit() {
        try {
            Map<String, String> params = new HashMap<>();
            params.put("symbol", "USTSITHKTSIT");
            params.put("side", "BUY");
            params.put("type", "LIMIT");
            params.put("timeInForce", "GTC");
            params.put("quantity", "1");
            params.put("price", "0.1");

            String response = apiClient.postWithSignature("/openapi/v1/order/test", params);
            assertNotNull(response);
            assertEquals("{}", response);
            System.out.println("Test new order (LIMIT) response: " + response);
        } catch (Exception e) {
            fail("Test new order (LIMIT) failed: " + e.getMessage());
        }
    }

