    @Test
    @DisplayName("Test /openapi/v1/order - Create new order (Note: This creates a real order)")
    public void testCreateNewOrder() {
        try {
            Map<String, String> params = new HashMap<>();
            params.put("symbol", "USTSITHKTSIT");
            params.put("side", "BUY");
            params.put("type", "LIMIT");
            params.put("timeInForce", "GTC");
            params.put("quantity", "1000");
            params.put("price", "0.1");
            params.put("newClientOrderId", "test-order-" + System.currentTimeMillis());
            System.out.println(params.get("newClientOrderId"));

            // WARNING: This will create a real order
            // Comment out in production or use test environment
//            System.out.println("WARNING: Create order test is disabled to prevent accidental orders");
             String response = apiClient.postWithSignature("/openapi/v1/order", params);
             System.out.println(response);
             assertNotNull(response);
             assertTrue(response.contains("orderId") || response.contains("clientOrderId"));
             System.out.println("Create new order response: " + response);
        } catch (Exception e) {
            fail("Create new order test failed: " + e.getMessage());
        }
    }
