    @Test
    @DisplayName("Test /openapi/v1/order - Cancel order by orderId")
    public void testCancelOrderByOrderId() {
        try {
            Map<String, String> params = new HashMap<>();
            params.put("orderId", "2098039228298471168");

            // WARNING: This will cancel a real order
//            System.out.println("WARNING: Cancel order test is disabled to prevent accidental cancellations");
             String response = apiClient.deleteWithSignature("/openapi/v1/order", params);
             assertNotNull(response);
             assertTrue(response.contains("status"));
             System.out.println("Cancel order (orderId) response: " + response);
        } catch (Exception e) {
            System.out.println("Note: Cancel order test - " + e.getMessage());
        }
    }

